activity.solution:
raw = [('Mumbai', '1200'), ('Delhi', '5000'), ('Delhi', 'N/A'), ('Pune', '450'), ('Mumbai', ''), ('Delhi', '3500')]
def clean(rows):
    good, bad = [], 0
    for city, amt in rows:
        try:
            good.append((city, float(amt)))
        except ValueError:
            bad += 1
    return good, bad
def aggregate(rows):
    out = {}
    for city, a in rows:
        out[city] = out.get(city, 0) + a
    return out
good, rejects = clean(raw)
for city, t in sorted(aggregate(good).items()):
    print(city, int(t))
print('rejects', rejects)

